// popup.js — NewsDesk 离线模式面板逻辑

(function () {
  const QUEUE_KEY = "newsdesk_queue";
  const CONFIG_KEY = "newsdesk_config";

  // ── Tab 切换 ────────────────────────────────────────────────────────────────
  document.querySelectorAll(".tab").forEach((tab) => {
    tab.addEventListener("click", () => {
      document.querySelectorAll(".tab").forEach((t) => t.classList.remove("active"));
      document.querySelectorAll(".panel").forEach((p) => p.classList.remove("active"));
      tab.classList.add("active");
      const target = document.getElementById("panel-" + tab.dataset.tab);
      if (target) target.classList.add("active");
      if (tab.dataset.tab === "queue") loadQueue();
      if (tab.dataset.tab === "stats") loadStats();
      if (tab.dataset.tab === "config") loadConfig();
    });
  });

  // ── 加载队列 ────────────────────────────────────────────────────────────────
  function loadQueue() {
    chrome.storage.local.get(QUEUE_KEY, (s) => {
      const raw = s[QUEUE_KEY];
      const items = Array.isArray(raw) ? raw : Array.isArray(raw?.items) ? raw.items : [];
      const pending = items.filter((it) => it.status === "pending" || it.status === "modified");
      document.getElementById("queueCount").textContent = `(${pending.length})`;
      renderQueue(pending);
    });
  }

  function renderQueue(items) {
    const container = document.getElementById("queueList");
    if (!items || items.length === 0) {
      container.innerHTML = `<div class="empty-state">
        <div class="icon">📭</div>
        <div>暂无新闻</div>
        <div style="margin-top:4px;font-size:11px;">点击「抓取新闻」开始</div>
      </div>`;
      return;
    }
    container.innerHTML = "";
    for (const item of items) {
      const card = document.createElement("div");
      card.className = "queue-item";
      const scoreColor = item.event_score >= 5 ? "var(--green)" : item.event_score >= 3 ? "var(--yellow)" : "var(--text-dim)";
      const drafts = item.drafts || {};
      const platKeys = Object.keys(drafts);

      let draftsHtml = "";
      if (platKeys.length > 0) {
        draftsHtml = '<div class="draft-editor">';
        for (const plat of platKeys) {
          draftsHtml += `<div class="plat-label">${platDisplay(plat)}</div>`;
          draftsHtml += `<textarea data-item="${item.item_id}" data-plat="${plat}">${escapeHtml(drafts[plat] || "")}</textarea>`;
        }
        draftsHtml += '</div>';
      }

      card.innerHTML = `
        <div class="qi-title">${escapeHtml(item.event_title)}</div>
        <div class="qi-meta">
          <span style="color:${scoreColor};font-weight:700;">★ ${item.event_score.toFixed(1)}</span>
          <span style="margin:0 6px;">·</span>
          ${(item.event_tags || []).map((t) => `<span class="tag">${t}</span>`).join("")}
          <span style="margin-left:6px;opacity:.6;">${timeAgo(item.created_at)}</span>
        </div>
        ${draftsHtml}
        <div class="qi-actions">
          <button class="btn-open" data-action="open" data-url="${escapeAttr(item.event_url)}">🔗 原文</button>
          <button class="btn-approve" data-id="${item.item_id}">✓ 批准</button>
          <button class="btn-reject" data-id="${item.item_id}">✗ 拒绝</button>
        </div>`;
      container.appendChild(card);
    }

    // 绑定修改草稿事件
    container.querySelectorAll("textarea").forEach((ta) => {
      ta.addEventListener("blur", (e) => {
        const id = e.target.dataset.item;
        const plat = e.target.dataset.plat;
        const text = e.target.value;
        chrome.runtime.sendMessage({ type: "MODIFY_DRAFT", itemId: id, platform: plat, text }, () => {});
      });
      // 自动展开高度
      ta.addEventListener("input", function () {
        this.style.height = "auto";
        this.style.height = this.scrollHeight + "px";
      });
      // 初始展开
      requestAnimationFrame(() => {
        ta.style.height = "auto";
        ta.style.height = ta.scrollHeight + "px";
      });
    });

    // 绑定按钮事件（使用事件委托）
    container.addEventListener("click", (e) => {
      const btn = e.target.closest("button");
      if (!btn) return;
      if (btn.classList.contains("btn-approve")) {
        approveItem(btn.dataset.id);
      } else if (btn.classList.contains("btn-reject")) {
        rejectItem(btn.dataset.id);
      } else if (btn.dataset.action === "open") {
        const url = btn.dataset.url;
        if (url) chrome.tabs.create({ url });
      }
    });
  }

  function approveItem(itemId) {
    chrome.runtime.sendMessage({ type: "APPROVE_ITEM", itemId }, (res) => {
      if (chrome.runtime.lastError) {
        console.error("APPROVE error:", chrome.runtime.lastError);
        alert("批准失败: " + chrome.runtime.lastError.message);
        return;
      }
      if (res?.ok) loadQueue();
      else alert("批准失败: " + (res?.error || "未知错误"));
    });
  }

  function rejectItem(itemId) {
    chrome.runtime.sendMessage({ type: "REJECT_ITEM", itemId }, (res) => {
      if (chrome.runtime.lastError) {
        console.error("REJECT error:", chrome.runtime.lastError);
        alert("拒绝失败: " + chrome.runtime.lastError.message);
        return;
      }
      if (res?.ok) loadQueue();
      else alert("拒绝失败: " + (res?.error || "未知错误"));
    });
  }

  // ── 加载统计 ────────────────────────────────────────────────────────────────
  function loadStats() {
    chrome.storage.local.get([QUEUE_KEY, QUEUE_KEY + "_stats"], (s) => {
      const raw = s[QUEUE_KEY];
      const allItems = Array.isArray(raw) ? raw : Array.isArray(raw?.items) ? raw.items : [];
      const counts = { pending: 0, approved: 0, rejected: 0, total: allItems.length };
      for (const it of allItems) {
        if (it.status === "pending" || it.status === "modified") counts.pending++;
        else if (it.status === "approved") counts.approved++;
        else if (it.status === "rejected") counts.rejected++;
      }
      document.getElementById("statPending").textContent = counts.pending;
      document.getElementById("statApproved").textContent = counts.approved;
      document.getElementById("statRejected").textContent = counts.rejected;
      document.getElementById("statTotal").textContent = counts.total;
    });
  }

  document.getElementById("clearAllBtn")?.addEventListener("click", () => {
    if (!confirm("确定要清空所有数据？此操作不可恢复。")) return;
    chrome.storage.local.remove([QUEUE_KEY, QUEUE_KEY + "_stats"], () => {
      alert("已清空全部数据。");
      loadQueue();
      loadStats();
    });
  });

  // ── 加载配置 ────────────────────────────────────────────────────────────────
  let _cfgCache = {}; // 缓存当前配置，避免闭包问题
  function loadConfig() {
    chrome.storage.sync.get(CONFIG_KEY, (s) => {
      const cfg = s[CONFIG_KEY] || {};
      _cfgCache = cfg;
      const el = (id) => document.getElementById(id);
      if (el("cfgStyle")) el("cfgStyle").value = cfg.style || "professional";
      if (el("cfgLang")) el("cfgLang").value = cfg.language || "zh";
      // LLM 配置
      if (el("cfgLLMEnabled")) el("cfgLLMEnabled").checked = !!cfg.llmEnabled;
      if (el("cfgLLMProvider")) el("cfgLLMProvider").value = cfg.llmProvider || "openai";
      if (el("cfgLLMKey")) el("cfgLLMKey").value = cfg.llmApiKey || "";
      if (el("cfgLLMBase")) el("cfgLLMBase").value = cfg.llmBaseUrl || "";
      if (el("cfgLLMModel")) el("cfgLLMModel").value = cfg.llmModel || "gpt-3.5-turbo";
      // toggles — 直接设置 class，不重复绑定事件
      const autoFetchEl = el("cfgAutoFetch");
      if (autoFetchEl) {
        autoFetchEl.classList.toggle("on", cfg.autoGenerate !== false);
      }
      const notifEl = el("cfgNotif");
      if (notifEl) {
        notifEl.classList.toggle("on", cfg.notifications !== false);
      }
      // platform toggles
      const platforms = cfg.platforms || ["x", "telegram", "discord"];
      document.querySelectorAll('[data-key]').forEach((tog) => {
        tog.classList.toggle("on", platforms.includes(tog.dataset.key));
      });
    });
  }

  // 给所有 toggle 元素绑定一次性点击事件（通过事件委托）
  document.addEventListener("click", (e) => {
    const tog = e.target.closest(".toggle");
    if (!tog) return;
    tog.classList.toggle("on");
  });

  document.getElementById("saveCfgBtn")?.addEventListener("click", () => {
    const cfg = {
      style: document.getElementById("cfgStyle")?.value || "professional",
      language: document.getElementById("cfgLang")?.value || "zh",
      autoGenerate: document.getElementById("cfgAutoFetch")?.classList.contains("on") ?? true,
      notifications: document.getElementById("cfgNotif")?.classList.contains("on") ?? true,
      platforms: [],
      // LLM 配置
      llmEnabled: document.getElementById("cfgLLMEnabled")?.checked ?? false,
      llmProvider: document.getElementById("cfgLLMProvider")?.value || "openai",
      llmApiKey: document.getElementById("cfgLLMKey")?.value || "",
      llmBaseUrl: document.getElementById("cfgLLMBase")?.value || "",
      llmModel: document.getElementById("cfgLLMModel")?.value || "gpt-3.5-turbo",
    };
    document.querySelectorAll('[data-key].on').forEach((t) => cfg.platforms.push(t.dataset.key));
    if (cfg.platforms.length === 0) cfg.platforms = ["x", "telegram", "discord"];
    chrome.storage.sync.set({ [CONFIG_KEY]: cfg }, () => {
      const btn = document.getElementById("saveCfgBtn");
      const orig = btn.textContent;
      btn.textContent = "✅ 已保存";
      setTimeout(() => (btn.textContent = orig), 1500);
      // 通知 background 更新 alarms / 配置
      chrome.runtime.sendMessage({ type: "CONFIG_UPDATED", cfg }, () => {});
    });
  });

  // ── 手动抓取按钮 ────────────────────────────────────────────────────────────
  document.getElementById("refreshBtn")?.addEventListener("click", () => {
    const btn = document.getElementById("refreshBtn");
    btn.disabled = true;
    btn.textContent = "⏳ 抓取中…";
    chrome.runtime.sendMessage({ type: "FETCH_AND_SCORE" }, (res) => {
      btn.disabled = false;
      btn.textContent = "🔄 抓取新闻";
      if (chrome.runtime.lastError) {
        alert("抓取失败: " + chrome.runtime.lastError.message);
        return;
      }
      if (res?.ok) {
        alert(`抓取完成！\n获取 ${res.fetched} 条，评分 ${res.scored} 条，新增 ${res.newItems} 条`);
        loadQueue();
        loadStats();
      } else {
        alert("抓取失败：" + (res?.error || "未知错误"));
      }
    });
  });

  // ── 初始化 ──────────────────────────────────────────────────────────────────
  loadQueue();

  // ── 工具函数 ────────────────────────────────────────────────────────────────
  function escapeHtml(str) {
    return String(str)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }

  function escapeAttr(str) {
    return String(str).replace(/'/g, "&#39;").replace(/"/g, "&quot;");
  }

  function timeAgo(isoStr) {
    if (!isoStr) return "";
    const diff = (Date.now() - new Date(isoStr).getTime()) / 1000;
    if (diff < 60) return "刚刚";
    if (diff < 3600) return Math.floor(diff / 60) + "分钟前";
    if (diff < 86400) return Math.floor(diff / 3600) + "小时前";
    return Math.floor(diff / 86400) + "天前";
  }

  function platDisplay(key) {
    const map = { x: "X / Twitter", telegram: "Telegram", discord: "Discord" };
    return map[key] || key;
  }
})();

// rss_fetcher.js
// 通过 Google RSS-to-JSON 公共接口绕过 CORS 抓取 RSS
// 备用：支持直接 fetch（开发环境 / 已配置 CORS 的服务器）
const RSS_PROXY = "https://api.rss2json.com/v1/api.json?rss_url=";

/**
 * 抓取单条 RSS feed，返回 [{title, summary, url, pubDate}] 列表
 * 超时 15s，失败自动重试一次
 */
async function fetchRSS(url, maxEntries = 25, timeoutMs = 15000) {
  const proxyUrl = RSS_PROXY + encodeURIComponent(url);
  try {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    const resp = await fetch(proxyUrl, { signal: controller.signal });
    clearTimeout(timer);
    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
    const json = await resp.json();
    if (json.status !== "ok") throw new Error(json.message || "rss2json error");
    return (json.items || [])
      .slice(0, maxEntries)
      .map((it) => ({
        title: (it.title || "").trim(),
        summary: cleanText(it.description || it.content || it.enclosure?.link || ""),
        url: it.link || "",
        pubDate: it.pubDate || it.isoDate || new Date().toISOString(),
        author: it.author || it.creator || "",
        thumbnail: it.thumbnail || it.image || "",
      }))
      .filter((it) => it.title && it.url);
  } catch (e) {
    console.warn("[NewsDesk] RSS fetch failed for", url, e.message);
    return [];
  }
}

function cleanText(text) {
  if (!text) return "";
  return text
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&#\d+;/g, "")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, 500);
}

// scorer.js — 关键词评分引擎（Python scoring.py 的等价实现）
const CRYPTO_KEYWORDS = [
  "bitcoin", "btc", "ethereum", "eth", "solana", "xrp", "ripple", "zcash",
  "litecoin", "cardano", "dogecoin", "defi", "etf", "clarity", "crypto",
  "blockchain", "rwa", "stablecoin", "nft", "layer2", "layer 2", "rollup",
  "zk", "zero-knowledge", "memecoin", "mempool", "sec", "regulation",
  "securities", "stock token", "synthetic", "tokenized", "payment",
  "banking", "exchange", "robinhood", "coinbase", "kraken", "bitget",
  "blackrock",
];
const AI_KEYWORDS = [
  "ai", "openai", "anthropic", "gpt", "claude", "llm", "agent", "model",
  "deepseek", "qwen", "gemini", "mistral",
  "cyber defense", "zero-day", "coding", "reasoning",
];
const SKIP_TERMS = [
  "giveaway", "airdrop code", "保证收益", "稳赚", "必涨", "100x", "moonshot",
];
const PREMIUM_TERMS = [
  "clarity", "etf", "regulation", "securities", "sec",
  "openai", "deepseek", "agent", "llm", "model",
  "payment", "banking", "blackrock", "robinhood", "coinbase",
  "tokenized", "rwa", "stablecoin", "memecoin", "reasoning", "cyber defense",
];
const SCORE_THRESHOLD = 2.0;
const MAX_AGE_HOURS = 48;
const MAX_ITEMS = 8;

/**
 * 评分一篇文章，返回 {score, tags, skipReason}
 */
function scoreArticle(title, summary) {
  const blob = (title + " " + summary).toLowerCase();

  // skip list
  for (const kw of SKIP_TERMS) {
    if (blob.includes(kw.toLowerCase())) {
      return { score: 0, tags: [], skipReason: `skip-term:${kw}` };
    }
  }

  const tags = [];
  let score = 0;

  const cryptoHits = CRYPTO_KEYWORDS.filter((w) => blob.includes(w.toLowerCase()));
  const aiHits = AI_KEYWORDS.filter((w) => blob.includes(w.toLowerCase()));

  if (cryptoHits.length) { tags.push("crypto"); score += cryptoHits.length; }
  if (aiHits.length)    { tags.push("ai");    score += aiHits.length; }

  if (tags.includes("crypto") && tags.includes("ai")) score += 2.5;
  for (const w of PREMIUM_TERMS) {
    if (blob.includes(w.toLowerCase())) { score += 1.5; break; }
  }

  return { score, tags, skipReason: null };
}

/**
 * 计算时效加分（0-6h 线性 +2.0→-1.0）
 */
function freshnessBonus(pubDateStr) {
  if (!pubDateStr) return -1.5;
  const pub = new Date(pubDateStr);
  if (isNaN(pub.getTime())) return -1.5;
  const ageHours = (Date.now() - pub.getTime()) / 3600000;
  if (ageHours > MAX_AGE_HOURS) return -999; // 丢弃
  return Math.max(-1.0, 2.0 - (ageHours / MAX_AGE_HOURS) * 3.0);
}

/**
 * 过滤并排序事件列表，返回 top N
 */
function collectEvents(rawItems) {
  const events = [];
  for (const item of rawItems) {
    const { score: rawScore, tags, skipReason } = scoreArticle(item.title, item.summary);
    if (skipReason) continue;
    if (rawScore < SCORE_THRESHOLD) continue;

    const fresh = freshnessBonus(item.pubDate);
    if (fresh <= -999) continue; // 过期

    const finalScore = rawScore + fresh;
    if (finalScore < SCORE_THRESHOLD) continue;

    events.push({
      ...item,
      score: parseFloat(finalScore.toFixed(2)),
      tags,
      rawScore: parseFloat(rawScore.toFixed(2)),
    });
  }

  // 去重（按标题前 40 字符）
  const seen = new Set();
  const uniq = [];
  for (const e of events.sort((a, b) => b.score - a.score)) {
    const key = e.title.slice(0, 40);
    if (seen.has(key)) continue;
    seen.add(key);
    uniq.push(e);
  }
  return uniq.slice(0, MAX_ITEMS);
}

from __future__ import annotations

import hashlib
import json
import time
from datetime import datetime, timezone
from pathlib import Path
from typing import Optional


def _encode_row(row):
    """把 fetch_rss 的 row (title, summary, url, pub_at) 序列化为 JSON 安全格式。"""
    title, summary, url, pub_at = row
    pub_iso = pub_at.isoformat() if pub_at else None
    return [title, summary, url, pub_iso]


def _decode_row(raw):
    """把 JSON 行还原为 (title, summary, url, datetime|None)。"""
    # 兼容旧缓存格式：3-tuple 无日期
    if len(raw) == 3:
        title, summary, url = raw
        return (title, summary, url, None)
    title, summary, url, pub_iso = raw
    pub_at = None
    if pub_iso:
        try:
            pub_at = datetime.fromisoformat(pub_iso)
            if pub_at.tzinfo is None:
                pub_at = pub_at.replace(tzinfo=timezone.utc)
        except ValueError:
            pub_at = None
    return (title, summary, url, pub_at)


class RSSCache:
    """简单的文件级缓存，按 URL 哈希存储 RSS 响应。"""

    def __init__(self, cache_dir: Path = Path(".cache/rss"), ttl_seconds: int = 3600):
        self._dir = cache_dir
        self._ttl = ttl_seconds
        self._dir.mkdir(parents=True, exist_ok=True)

    def get(self, url: str):
        key = self._key(url)
        meta_path = self._dir / f"{key}.meta"
        data_path = self._dir / f"{key}.json"
        if not meta_path.exists() or not data_path.exists():
            return None
        try:
            meta = json.loads(meta_path.read_text(encoding="utf-8"))
            if time.time() - meta["ts"] > self._ttl:
                return None
            raw_rows = json.loads(data_path.read_text(encoding="utf-8"))
            return [_decode_row(r) for r in raw_rows]
        except Exception:
            return None

    def set(self, url: str, data) -> None:
        key = self._key(url)
        meta_path = self._dir / f"{key}.meta"
        data_path = self._dir / f"{key}.json"
        meta_path.write_text(json.dumps({"ts": time.time()}, ensure_ascii=False), encoding="utf-8")
        encoded = [_encode_row(r) for r in data]
        data_path.write_text(json.dumps(encoded, ensure_ascii=False), encoding="utf-8")

    @staticmethod
    def _key(url: str) -> str:
        return hashlib.sha256(url.encode()).hexdigest()[:16]

from __future__ import annotations

import os
import time
from typing import Optional

try:
    from openai import OpenAI
except ImportError:  # pragma: no cover
    OpenAI = None  # type: ignore

from .models import LLMClient


def _cfg_llm() -> dict:
    """从 config.yaml 读取 llm section（环境变量覆盖链在各 resolve 里处理）。"""
    try:
        from .config import get_raw
        return get_raw().get("llm", {}) or {}
    except Exception:
        return {}


def _cfg_fallback_providers() -> list[dict]:
    """从 config.yaml 读取 llm_fallback section（多模型 fallback 链）。"""
    try:
        from .config import get_raw
        return get_raw().get("llm_fallback", []) or []
    except Exception:
        return []


def _resolve_api_key() -> str:
    env_key = os.environ.get("NEWSDESK_LLM_API_KEY", "").strip()
    if env_key:
        return env_key
    return _cfg_llm().get("api_key", "").strip()


def _resolve_base_url() -> Optional[str]:
    url = os.environ.get("NEWSDESK_LLM_BASE_URL", "").strip()
    if url:
        return url
    url = _cfg_llm().get("base_url", "").strip()
    return url or None


def _resolve_model() -> Optional[str]:
    m = os.environ.get("NEWSDESK_LLM_MODEL", "").strip()
    if m:
        return m or None
    m = _cfg_llm().get("model", "").strip()
    return m or None


def build_llm_client() -> Optional[LLMClient]:
    """构建 LLM 客户端，支持主模型 + fallback 链。"""
    api_key = _resolve_api_key()
    if not api_key:
        return None
    if OpenAI is None:
        print("警告：openai 包未安装，安装后使用 `pip install newsdesk[llm]`")
        return None

    primary_kwargs: dict[str, str] = {"api_key": api_key}
    base_url = _resolve_base_url()
    model = _resolve_model()
    if base_url:
        primary_kwargs["base_url"] = base_url

    primary = OpenAIClient(model=model, **primary_kwargs)

    # Fallback 链
    fallback_clients: list[LLMClient] = []
    for provider in _cfg_fallback_providers():
        fb_api_key = provider.get("api_key", "").strip()
        fb_base_url = provider.get("base_url", "").strip() or None
        fb_model = provider.get("model", "").strip() or None
        if not fb_api_key:
            continue
        fb_kwargs: dict[str, str] = {"api_key": fb_api_key}
        if fb_base_url:
            fb_kwargs["base_url"] = fb_base_url
        fb_client = OpenAIClient(model=fb_model, **fb_kwargs)
        fallback_clients.append(fb_client)
        print(f"  LLM fallback: {fb_model or 'default'} @ {fb_base_url or 'default'} 已注册")

    if fallback_clients:
        return FallbackLLMClient(primary=primary, fallbacks=fallback_clients)
    return primary


class OpenAIClient(LLMClient):
    def __init__(self, *, api_key: str, base_url: Optional[str] = None, model: Optional[str] = None):
        client_kwargs: dict[str, str] = {"api_key": api_key}
        if base_url:
            client_kwargs["base_url"] = base_url
        self._client = OpenAI(**client_kwargs)
        self._default_model = model

    def generate(self, prompt: str, model: Optional[str] = None) -> str:
        effective_model = model or self._default_model or "default"
        response = self._client.chat.completions.create(
            model=effective_model,
            messages=[{"role": "user", "content": prompt}],
            temperature=0.7,
            max_tokens=600,
        )
        return response.choices[0].message.content or ""


class FallbackLLMClient(LLMClient):
    """主模型失败时自动降级到备用模型链。"""

    def __init__(self, primary: OpenAIClient, fallbacks: list[LLMClient]):
        self._primary = primary
        self._fallbacks = fallbacks
        self._default_model = primary._default_model

    def generate(self, prompt: str, model: Optional[str] = None) -> str:
        # 先试主模型
        try:
            result = self._primary.generate(prompt, model=model)
            if result.strip():
                return result
        except Exception as exc:
            print(f"  LLM 主模型失败：{exc}，尝试 fallback...")

        # 逐个试 fallback
        for fb in self._fallbacks:
            try:
                result = fb.generate(prompt, model=model)
                if result.strip():
                    print(f"  ✓ Fallback 成功")
                    return result
            except Exception as exc:
                print(f"  Fallback 也失败：{exc}")
                time.sleep(0.5)
                continue

        # 全部失败
        raise RuntimeError("所有 LLM 模型（主 + fallback）均不可用")

