"""
流水线断点持久化 —— 借鉴 Sumbird 的 9 步断点设计。
每一步的输出都存为 data/*.json，可独立加载/跳过，LLM 中断后恢复不用重新爬。

目录结构：
data/
├── 01_fetched.json      ← RSS 原始抓取结果（含发布时间）
├── 02_scored.json       ← 评分 + 时效过滤后的 Event 列表
├── 03_drafts.json       ← 三平台文案草稿（可能部分由 LLM 生成）
└── state.json           ← 最近一次运行的 fetch hash，避免重复处理
"""
from __future__ import annotations

import hashlib
import json
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Optional

from .config import DATA_DIR
from .models import Event


_DATA = Path(DATA_DIR)
_FETCHED = _DATA / "01_fetched.json"
_SCORED = _DATA / "02_scored.json"
_DRAFTS = _DATA / "03_drafts.json"
_STATE = _DATA / "state.json"


def _ensure_dir() -> None:
    _DATA.mkdir(parents=True, exist_ok=True)


def _event_to_dict(e: Event) -> dict:
    return {
        "title": e.title,
        "summary": e.summary,
        "url": e.url,
        "score": e.score,
        "tags": e.tags,
        "published_at": e.published_at.isoformat() if e.published_at else None,
        "age_hours": e.age_hours,
    }


def _dict_to_event(d: dict) -> Event:
    pub = d.get("published_at")
    if pub:
        pub = datetime.fromisoformat(pub)
        if pub.tzinfo is None:
            pub = pub.replace(tzinfo=timezone.utc)
    return Event(
        title=d["title"],
        summary=d["summary"],
        url=d["url"],
        score=d["score"],
        tags=d.get("tags", []),
        published_at=pub,
        age_hours=d.get("age_hours", 0.0),
    )


def save_step(step: str, data: Any) -> Path:
    """保存一步的输出。step ∈ {'fetched', 'scored', 'drafts'}。"""
    _ensure_dir()
    mapping = {
        "fetched": _FETCHED,
        "scored": _SCORED,
        "drafts": _DRAFTS,
    }
    target = mapping.get(step)
    if target is None:
        raise ValueError(f"Unknown step: {step}")

    serializable = data
    if step == "scored" and isinstance(data, list) and data and isinstance(data[0], Event):
        serializable = [_event_to_dict(e) for e in data]

    payload = {
        "saved_at": datetime.now(timezone.utc).isoformat(),
        "step": step,
        "count": len(data) if hasattr(data, "__len__") else None,
        "data": serializable,
    }
    target.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
    return target


def load_step(step: str) -> Optional[Any]:
    """加载某一步的中间产物，不存在返回 None。"""
    mapping = {"fetched": _FETCHED, "scored": _SCORED, "drafts": _DRAFTS}
    target = mapping.get(step)
    if target is None or not target.exists():
        return None
    try:
        payload = json.loads(target.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, OSError):
        return None
    data = payload.get("data")
    if step == "scored" and isinstance(data, list):
        return [_dict_to_event(d) for d in data]
    return data


def fetch_hash(title: str, url: str) -> str:
    """为一条新闻生成稳定 hash，用于重复检测。"""
    return hashlib.sha256(f"{title[:60]}|{url}".encode()).hexdigest()[:16]


def load_state() -> dict:
    if _STATE.exists():
        try:
            return json.loads(_STATE.read_text(encoding="utf-8"))
        except Exception:
            pass
    return {"last_fetch_hashes": [], "last_run": None}


def save_state(state: dict) -> None:
    _ensure_dir()
    _STATE.write_text(json.dumps(state, ensure_ascii=False, indent=2), encoding="utf-8")


def save_drafts(drafts_map: dict[int, dict[str, str]]) -> Path:
    """drafts 持久化：{idx: {platform: text}}"""
    return save_step("drafts", drafts_map)


def load_drafts() -> Optional[dict[int, dict[str, str]]]:
    raw = load_step("drafts")
    if raw is None:
        return None
    # JSON keys are strings，转回 int
    return {int(k): v for k, v in raw.items()}

"""
多平台发布适配器 —— Twitter/X (API v2)、Telegram Bot、Discord Webhook。

设计原则：
- 直接用 requests 调用，不引入 tweepy / python-telegram-bot / discord.py 重依赖
- 每个平台实现 Publisher 协议，统一 publish(text, options) 接口
- 所有 HTTP 调用带超时和重试，失败时抛出 PublisherError 由上层决定
- 不持有用户凭证（凭证从 config.yaml 或环境变量读取）
"""
from __future__ import annotations

import os
import time
from dataclasses import dataclass, field
from datetime import datetime, timezone
from typing import Optional, Protocol

try:
    import requests
except ImportError:  # 打包 EXE 时确保可用
    requests = None  # type: ignore


# ---------------------------------------------------------------------------
# 异常 + 结果
# ---------------------------------------------------------------------------

class PublisherError(Exception):
    """发布失败的统一异常。"""

    def __init__(self, platform: str, message: str, http_status: int | None = None):
        self.platform = platform
        self.http_status = http_status
        super().__init__(f"[{platform}] {message}")


@dataclass
class PublishResult:
    """单次发布结果。"""
    platform: str
    success: bool
    external_id: str = ""          # 平台返回的帖子 ID
    error: str = ""
    published_at: datetime = field(default_factory=lambda: datetime.now(timezone.utc))


# ---------------------------------------------------------------------------
# 协议
# ---------------------------------------------------------------------------

class Publisher(Protocol):
    platform: str

    def publish(self, text: str, *, image_url: str | None = None, **kw) -> PublishResult: ...
    def check_credentials(self) -> bool: ...


# ---------------------------------------------------------------------------
# Twitter / X  (API v2, OAuth 2.0 Bearer Token + POST /2/tweets)
# ---------------------------------------------------------------------------

@dataclass
class TwitterPublisher:
    """Twitter X API v2 发布。

    凭证来源（优先级从高到低）：
      1. 构造函数传入的 bearer_token
      2. 环境变量 TWITTER_BEARER_TOKEN 或 TWITTER_API_KEY/TWITTER_API_SECRET 或 TWITTER_OAUTH_TOKEN/TWITTER_OAUTH_SECRET
      3. config.yaml → publisher.twitter.*
    """
    bearer_token: str = ""
    api_key: str = ""
    api_secret: str = ""
    oauth_token: str = ""
    oauth_secret: str = ""
    base_url: str = "https://api.twitter.com/2"
    timeout: int = 20
    max_retries: int = 2

    platform: str = "twitter"

    @classmethod
    def from_config(cls, cfg: dict | None = None) -> "TwitterPublisher":
        """从全局配置或环境变量构造。"""
        cfg = cfg or {}
        tw_cfg = cfg.get("twitter", {}) if isinstance(cfg, dict) else {}
        return cls(
            bearer_token=os.environ.get("TWITTER_BEARER_TOKEN") or tw_cfg.get("bearer_token", ""),
            api_key=os.environ.get("TWITTER_API_KEY") or tw_cfg.get("api_key", ""),
            api_secret=os.environ.get("TWITTER_API_SECRET") or tw_cfg.get("api_secret", ""),
            oauth_token=os.environ.get("TWITTER_OAUTH_TOKEN") or tw_cfg.get("oauth_token", ""),
            oauth_secret=os.environ.get("TWITTER_OAUTH_SECRET") or tw_cfg.get("oauth_secret", ""),
        )

    def check_credentials(self) -> bool:
        return bool(self.bearer_token) or (bool(self.api_key) and bool(self.oauth_token))

    def publish(self, text: str, *, thread: list[str] | None = None, **kw) -> PublishResult:
        if requests is None:
            return PublishResult("twitter", False, error="requests 未安装")

        if not self.check_credentials():
            return PublishResult("twitter", False, error="缺少 Twitter API 凭证（Bearer Token 或 OAuth）")

        # 单帖上限 280 字，thread 可以发多帖
        if len(text) > 280:
            # 自动截断到 280 字符（按 X 的 grapheme 计数）
            text = text[:277] + "…"

        url = f"{self.base_url}/tweets"
        headers = self._auth_headers()

        # 处理 thread（如果有 reply_to_id 则作为回复发）
        tweets_to_send = thread or [text]
        last_tweet_id: str = ""
        results: list[PublishResult] = []

        for idx, t_text in enumerate(tweets_to_send):
            if len(t_text) > 280:
                t_text = t_text[:277] + "…"

            payload: dict = {"text": t_text}
            if last_tweet_id:
                payload["reply"] = {"in_reply_to_tweet_id": last_tweet_id}

            result = self._post_with_retry(url, headers, payload)
            results.append(result)
            if result.success and result.external_id:
                last_tweet_id = result.external_id
            else:
                # thread 中间失败则停止
                return result

        return results[-1] if results else PublishResult("twitter", False, error="未发送任何内容")

    def _auth_headers(self) -> dict:
        if self.bearer_token:
            return {"Authorization": f"Bearer {self.bearer_token}", "Content-Type": "application/json"}
        # OAuth 1.0a 简化方案（需要 requests-oauthlib，这里退化成 bearer token）
        # 如果用户配置了 OAuth 凭证，我们提示需要完整安装
        return {"Content-Type": "application/json"}

    def _post_with_retry(self, url: str, headers: dict, payload: dict) -> PublishResult:
        last_error = ""
        for attempt in range(self.max_retries + 1):
            try:
                resp = requests.post(url, json=payload, headers=headers, timeout=self.timeout)
                if resp.status_code == 201:
                    data = resp.json()
                    return PublishResult(
                        "twitter",
                        True,
                        external_id=str(data.get("data", {}).get("id", "")),
                    )
                elif resp.status_code in (429, 500, 502, 503):
                    wait = 2 ** attempt
                    time.sleep(wait)
                    last_error = f"HTTP {resp.status_code} (重试)"
                else:
                    last_error = f"HTTP {resp.status_code}: {resp.text[:200]}"
                    break
            except requests.RequestException as exc:
                last_error = str(exc)
                if attempt < self.max_retries:
                    time.sleep(2 ** attempt)

        return PublishResult("twitter", False, error=last_error)


